import pypdf

reader = pypdf.PdfReader("/tmp/key_indicators.pdf")
print("Num pages:", len(reader.pages))

# Search for "Unemployment Rate" or "Table" or state names in the pages
for i, page in enumerate(reader.pages):
    text = page.extract_text()
    if "Unemployment Rate" in text or "usual status" in text.lower() or "state" in text.lower():
        if "Table" in text:
            print(f"Page {i+1}: {text[:300]}...\n")
